// =====================================================================
//  Datendiskrepanz-Sweep: faellige Aktion bestimmen + Text erzeugen
//
//  MUSS SYNCHRON GEHALTEN WERDEN mit feldmark_app/server/datendiskrepanz.js
//  - dieselbe Logik existiert bewusst zweimal (Nutzerentscheidung vom
//  2026-08-14: Duplizierung statt Deployment, siehe KONTEXT.md und die
//  Sticky Note links). Aendert sich eine Frist-Schwelle oder ein
//  Textbaustein dort, muss dieser Code-Node manuell nachgezogen werden.
// =====================================================================

const NACHFASSUNG_1_TAGE = 3;
const NACHFASSUNG_2_TAGE = 6;
const FRISTWAHREND_SPAETESTENS_TAG = 10;
const SCHLIESSEN_NACH_TAGEN = 30;

function tageSeit(datumWert) {
  if (!datumWert) return null;
  return Math.floor((Date.now() - new Date(datumWert).getTime()) / 86400000);
}
const heute = () => new Date().toLocaleDateString('de-DE');
const datum = (iso) => new Date(iso).toLocaleDateString('de-DE');

function erzeugeNachfassung(f, nummer) {
  return [
    `NACHFASSUNG ${nummer} zur Rückfrage vom ${datum(f.rueckfrage_gesendet_am)}`,
    ``,
    `Ihr Aktenzeichen: ${f.aktenzeichen}`,
    `Unser Aktenzeichen: ${f.fall_id}`,
    ``,
    `Sehr geehrte Damen und Herren,`,
    ``,
    `wir haben Ihnen am ${datum(f.rueckfrage_gesendet_am)} eine Rückfrage zur Identifikation des Schuldners im oben genannten Vorgang übersandt und bislang keine Antwort erhalten.`,
    ``,
    `Bitte teilen Sie uns die angefragten Angaben kurzfristig mit.`,
    ``,
    `Mit freundlichen Grüßen`,
    `Feldmark Bank AG`,
    ``,
    `— automatisch erzeugt am ${heute()} —`,
  ].join('\n');
}

function erzeugeFristwahrendeErklaerung(f) {
  return [
    `DRITTSCHULDNERERKLÄRUNG gemäß § 840 ZPO`,
    ``,
    `Ihr Aktenzeichen: ${f.aktenzeichen}`,
    `Unser Aktenzeichen: ${f.fall_id}`,
    `Zustellung des Schreibens: ${datum(f.zustelldatum)}`,
    ``,
    `Sehr geehrte Damen und Herren,`,
    ``,
    `zu dem oben genannten Vorgang erklären wir gemäß § 840 Abs. 1 ZPO wie folgt:`,
    ``,
    `1. Eine Geschäftsverbindung zu dem in Ihrem Schreiben bezeichneten Schuldner konnte anhand der uns vorliegenden Daten nicht festgestellt werden. Wir haben Sie hierzu am ${datum(f.rueckfrage_gesendet_am)} um ergänzende Angaben gebeten; eine für die Zuordnung ausreichende Antwort liegt bis heute nicht vor.`,
    `2. Diese Erklärung wahrt die gesetzliche Frist. Sollte die Zuordnung anhand nachträglich eingehender Angaben gelingen, wird der Vorgang unverzüglich erneut geprüft und, falls zutreffend, eine ergänzende Erklärung nach § 840 ZPO abgegeben.`,
    ``,
    `Mit freundlichen Grüßen`,
    `Feldmark Bank AG`,
    ``,
    `— automatisch erzeugt am ${heute()}, vor Versand durch Mitarbeiter zu bestätigen —`,
  ].join('\n');
}

const out = [];
for (const item of $input.all()) {
  const f = item.json;
  const tageSeitZustellung = tageSeit(f.zustelldatum);
  const tageSeitRueckfrage = tageSeit(f.rueckfrage_gesendet_am);

  let aktion = 'keine';
  let text = null;

  if (tageSeitZustellung >= FRISTWAHREND_SPAETESTENS_TAG && !f.fristwahrend_erklaert_am) {
    aktion = 'fristwahrend_erklaert';
    text = erzeugeFristwahrendeErklaerung(f);
  } else if (tageSeitRueckfrage >= SCHLIESSEN_NACH_TAGEN) {
    aktion = 'geschlossen_ungeklaert';
  } else if (tageSeitRueckfrage >= NACHFASSUNG_2_TAGE && !f.nachfassung_2_gesendet_am) {
    aktion = 'nachfassung_2';
    text = erzeugeNachfassung(f, 2);
  } else if (tageSeitRueckfrage >= NACHFASSUNG_1_TAGE && !f.nachfassung_1_gesendet_am) {
    aktion = 'nachfassung_1';
    text = erzeugeNachfassung(f, 1);
  }

  out.push({ json: { ...f, aktion, text } });
}
return out;
